mapper.select:
SELECT i.id, i.coupon_id AS couponId, i.status, i.used_order_id AS usedOrderId, i.used_at AS usedAt, c.coupon_name AS couponName, c.discount_type AS discountType, c.discount_value AS discountValue, c.min_order_amount AS minOrderAmount, c.valid_to AS validTo, AS effectiveStatus FROM xsy_promotion_coupon_instance i JOIN xsy_promotion_coupon c ON c.id = i.coupon_id WHERE i.customer_id = #{customerId}
AND i.status = 'AVAILABLE' AND c.deleted = FALSE AND c.status = 'ACTIVE' AND c.valid_from <= #{at} AND c.valid_to > #{at}
AND i.status = 'USED'
AND i.status <> 'USED' AND NOT (i.status = 'AVAILABLE' AND c.deleted = FALSE AND c.status = 'ACTIVE' AND c.valid_from <= #{at} AND c.valid_to > #{at})
ORDER BY i.id DESC
